/* Page-level navigation for the Software I workspace.  It changes only the
   presentation of existing modules; inputs, records, and routing state stay in place. */
(() => {
  const work=document.querySelector('.module-workspace');if(!work)return;
  const zh=()=>document.documentElement.lang==='zh-Hant';
  const pages=new Map(),host=document.createElement('div'),tabs=document.createElement('nav');
  host.id='workspacePageHost';tabs.id='workspacePageTabs';tabs.setAttribute('aria-label','Software I pages');
  ['route','screen','evidence','learn'].forEach(id=>{const page=document.createElement('section');page.className='workspace-page';page.dataset.page=id;pages.set(id,page);host.appendChild(page);});
  work.insertBefore(host,work.firstChild);
  const move=(id,page)=>{const el=document.getElementById(id);if(el)pages.get(page).appendChild(el);};
  ['userGuide','mod-inflow','mod-storage','mod-outlet','mod-routing'].forEach(id=>move(id,'route'));
  const contract=work.querySelector('.principle-contract');if(contract)pages.get('route').insertBefore(contract,pages.get('route').firstChild);
  move('mod-optimization','screen');move('mod-evaluation','evidence');move('teachingAssistant','learn');move('qualityAssurance','learn');
  let active='route';
  const pageLabels=()=>zh()?[['route','設定與路由','模組 1–4'],['screen','受限設計篩選','模組 5'],['evidence','結果、驗證與紀錄','模組 6'],['learn','教學與內部測試','自學／QA']]:[['route','Setup and routing','Modules 1–4'],['screen','Constrained screening','Module 5'],['evidence','Results, verification and records','Module 6'],['learn','Teaching and internal tests','Learning / QA']];
  const childLabels=()=>zh()?{route:[['mod-inflow','1. 入流邊界'],['mod-storage','2. 蓄水量—水位狀態'],['mod-outlet','3. 出口水理'],['mod-routing','4. 第一性原理路由演算']],screen:[['mod-optimization','5. 受限設計篩選']],evidence:[['mod-evaluation','6. 評估與決策支援']],learn:[['teachingAssistant','教學輔助｜四步自學']]}:{route:[['mod-inflow','1. Inflow boundary'],['mod-storage','2. Storage–water-level state'],['mod-outlet','3. Outlet hydraulics'],['mod-routing','4. First-principles routing']],screen:[['mod-optimization','5. Constrained design screening']],evidence:[['mod-evaluation','6. Evaluation and decision support']],learn:[['teachingAssistant','Teaching support | four-step learning']]};
  function sidebar(){const nav=document.getElementById('moduleNavContent');if(!nav)return;let detail=nav.querySelector('#workspaceModuleNav');if(!detail){detail=document.createElement('div');detail.id='workspaceModuleNav';nav.insertBefore(detail,nav.querySelector('.future-caption')||null);}nav.querySelectorAll('.module-link').forEach(link=>{if(!detail.contains(link))link.hidden=true;});detail.innerHTML=(childLabels()[active]||[]).map(([target,label])=>`<button type="button" class="module-link workspace-child" data-workspace-target="${target}">${label}</button>`).join('');detail.hidden=!detail.children.length;}
  function mount(){const nav=document.getElementById('moduleNavContent');if(!nav)return;nav.insertBefore(tabs,nav.querySelector('#workspaceModuleNav')||nav.querySelector('.module-link')||nav.querySelector('.future-caption')||null);}
  function draw(){mount();tabs.innerHTML=pageLabels().map(([id,title,sub])=>`<button type="button" class="workspace-tab${id===active?' active':''}" data-workspace-page="${id}" aria-selected="${id===active}"><span>${title}</span><small>${sub}</small></button>`).join('');pages.forEach((page,id)=>{page.hidden=id!==active;});sidebar();}
  function activate(id,scroll=true){if(!pages.has(id))return;active=id;draw();if(scroll)pages.get(id).scrollIntoView({behavior:'smooth',block:'start'});}
  function openTarget(id){const page={'mod-inflow':'route','mod-storage':'route','mod-outlet':'route','mod-routing':'route','mod-optimization':'screen','mod-evaluation':'evidence','teachingAssistant':'learn'}[id];if(page)activate(page,false);document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'});}
  document.addEventListener('click',event=>{const main=event.target.closest?.('[data-workspace-page]');if(main){event.preventDefault();activate(main.dataset.workspacePage);return;}const child=event.target.closest?.('[data-workspace-target]');if(child){event.preventDefault();openTarget(child.dataset.workspaceTarget);return;}const module=event.target.closest?.('.module-link[data-target]');if(module)openTarget(module.dataset.target);if(event.target.closest?.('#teachingNavButton'))openTarget('teachingAssistant');},true);
  document.getElementById('run')?.addEventListener('click',()=>window.setTimeout(()=>activate('evidence'),120));
  document.getElementById('lang')?.addEventListener('click',()=>window.setTimeout(draw,0));
  const style=document.createElement('style');style.textContent=`#workspacePageTabs{display:grid;gap:5px;margin:0 0 12px}.workspace-tab{border:1px solid #b9d4df;border-radius:5px;background:#fff;color:#123247;text-align:left;padding:8px 9px;cursor:pointer;font:inherit}.workspace-tab span{display:block;font-weight:700;font-size:14px}.workspace-tab small{display:block;color:#526a78;font-size:11px;margin-top:1px}.workspace-tab:hover{background:#eef8fb;border-color:#0b557d}.workspace-tab.active{background:#0b557d;color:#fff;border-color:#0b557d}.workspace-tab.active small{color:#dbeef5}#workspaceModuleNav{display:grid;gap:5px;margin:0 0 12px;padding:8px;border:1px solid #d6e3e8;border-radius:6px;background:#f8fbfc}#workspaceModuleNav .module-link{margin:0;background:#fff}.workspace-page[hidden]{display:none!important}.workspace-page>.module-card,.workspace-page>#teachingAssistant,.workspace-page>#qualityAssurance{margin-top:0;margin-bottom:18px}.workspace-page>#mod-evaluation{margin-top:0}@media(max-width:850px){#workspacePageTabs,#workspaceModuleNav{grid-column:1/-1;grid-template-columns:1fr 1fr}.workspace-tab{min-height:54px}}`;document.head.appendChild(style);
  draw();window.DSSWorkspacePages=Object.freeze({activate,active:()=>active});
})();
